const sd=$getWorkflowStaticData('global'); if(!sd.drafts) sd.drafts=[];
const b=$json.body||{};
const platform=(b.platform||'facebook').toLowerCase();
let kind = platform==='both' ? 'fb_post+ig_post' : (platform==='instagram' ? 'ig_post' : 'fb_post');
const id='d'+Date.now().toString(36);
const draft={id, kind, target:platform, payload:{message:b.message||'', image_url:b.image_url||''}, status:'pending', createdAt:new Date().toISOString()};
sd.drafts.push(draft);
const preview=(b.message||'').replace(/\s+/g,' ').slice(0,90);
let note = (platform!=='facebook' && !b.image_url) ? ' (note: Instagram requires an image_url to publish)' : '';
return [{json:{summary:`Draft ${id} staged for ${platform}${note}: ${preview}`}}];

const sd=$getWorkflowStaticData('global');
const ds=(sd.drafts||[]).filter(d=>d.status==='pending');
if(!ds.length) return [{json:{summary:'No pending drafts.'}}];
const lines=ds.slice(0,10).map(d=>`${d.id} [${d.kind}]: ${(d.payload.message||d.payload.text||'').replace(/\s+/g,' ').slice(0,70)}`);
return [{json:{summary:`Pending drafts (${ds.length}):\n`+lines.join('\n')}}];

const sd=$getWorkflowStaticData('global'); if(!sd.drafts) sd.drafts=[];
const b=$json.body||{};
const platform=(b.platform||'facebook').toLowerCase();
const kind = platform==='instagram' ? 'ig_comment' : 'fb_comment';
const id='d'+Date.now().toString(36);
const draft={id, kind, target:(b.target||b.comment_id||b.post_id||''), payload:{message:b.message||b.text||''}, status:'pending', createdAt:new Date().toISOString()};
sd.drafts.push(draft);
const preview=(draft.payload.message||'').replace(/\s+/g,' ').slice(0,90);
return [{json:{summary:`Reply draft ${id} staged (${kind}) to ${draft.target||'(no target)'}: ${preview}`}}];

const sd=$getWorkflowStaticData('global'); if(!sd.drafts) sd.drafts=[];
const b=$json.body||{};
const id='d'+Date.now().toString(36);
const draft={id, kind:'ad_change', target:(b.target||b.campaign_id||b.adset_id||''),
  payload:{action:(b.action||'pause'), value:(b.value!=null?b.value:null), level:(b.level||'campaign')},
  status:'pending', createdAt:new Date().toISOString()};
sd.drafts.push(draft);
return [{json:{summary:`Ad-change draft ${id} staged: ${draft.payload.action} ${draft.payload.value!=null?('to '+draft.payload.value):''} on ${draft.payload.level} ${draft.target||'(no id)'} (approval required)`}}];

const PT=$('PageToken').first().json.access_token; const H=this.helpers;
const PAGE='{{FACEBOOK_PAGE_ID}}', IG='{{INSTAGRAM_BUSINESS_ID}}';
const sd=$getWorkflowStaticData('global'); const ds=sd.drafts||[];
const id=(($('Hook_publish').first().json.body)||{}).id;
const d=ds.find(x=>x.id===id);
if(!d) return [{json:{summary:`No draft ${id} found. Use meta_list_drafts to see pending drafts.`}}];
if(d.status==='published') return [{json:{summary:`Draft ${id} was already published.`}}];
async function post(path,params){ return await H.httpRequest({method:'POST',url:'https://graph.facebook.com/v21.0/'+path,qs:Object.assign({access_token:PT},params),json:true}); }
const results=[];
try{
  if(d.kind.indexOf('fb_post')>=0){ const r=await post(PAGE+'/feed',{message:d.payload.message}); d.fbId=r.id; results.push('FB post '+r.id); }
  if(d.kind.indexOf('ig_post')>=0){
    if(!d.payload.image_url){ results.push('IG skipped (no image_url)'); }
    else { const cr=await post(IG+'/media',{caption:d.payload.message, image_url:d.payload.image_url}); const pub=await post(IG+'/media_publish',{creation_id:cr.id}); d.igId=pub.id; results.push('IG post '+pub.id); }
  }
  if(d.kind==='fb_comment'){ const r=await post(d.target+'/comments',{message:d.payload.message}); d.fbId=r.id; results.push('FB comment '+r.id); }
  if(d.kind==='ig_comment'){ const r=await post(d.target+'/replies',{message:d.payload.message}); d.igId=r.id; results.push('IG reply '+r.id); }
  if(d.kind==='ad_change'){
    const p=d.payload; const body={};
    if(p.action==='pause') body.status='PAUSED';
    else if(p.action==='resume'||p.action==='activate') body.status='ACTIVE';
    else if(p.action==='budget'&&p.value!=null) body.daily_budget=Math.round(Number(p.value)*100);
    const r=await post(d.target,body); results.push('ad change ok'); d.adResult=r;
  }
  d.status='published'; d.publishedAt=new Date().toISOString();
  return [{json:{summary:`Published draft ${id}: `+results.join(', ')}}];
}catch(e){
  const m=(e&&e.message)?e.message:String(e);
  return [{json:{summary:`Publish FAILED for draft ${id}: `+m.slice(0,180)}}];
}
